    const max = Number(m.max) > min ? Number(m.max) : 1
    const raw = m.valueKey && state && state[m.valueKey] != null ? Number(state[m.valueKey]) : Number(m.value)
    const value = Number.isFinite(raw) ? Math.max(min, Math.min(max, raw)) : min
